char *ptr; // pointer to character
// Pointer arithmetic for substring extraction
ptr = base_address + offset; // move pointer by offset
// Using pointer in functions to process substrings
char *substr = ptr; // start of substring
// To get substring length: end_ptr - start_ptr

code_example:
char *base = "Advanced C techniques";
size_t pos = 8;
char *substr_start = base + pos;
size_t substr_length = strlen(base) - pos;
char buffer[50];
memcpy(buffer, substr_start, substr_length);
buffer[substr_length] = '\0'; // null-terminate the substring
printf("Substring: %s\n", buffer);
